"""The mounted backup directory, reset to a declared set before a run (plan D17).

`GRAMPS_BACKUP_DIR` is a bind mount: it outlives the container, the test and the run. That
makes two false greens available for free, and both have to be closed structurally rather
than by remembering to clean up:

* **A leftover export answers "did it export?" with yes.** So nothing here asks whether a
  file exists — it asks which files appeared *during this call*, against a listing taken
  before it.
* **The default export name is a 1-second-resolution timestamp** (`backup_store.py:16-20`),
  so two default exports inside the same second overwrite each other and the second one looks
  like it never happened. `assert_export` therefore takes `filename=` as a required keyword:
  there is no way to assert an export without naming the file.

The reset also verifies what it copies. A fixture that silently drifted from the committed
digest would recalibrate every count assertion downstream, and nothing else in the suite is
positioned to notice.
"""

from __future__ import annotations

import hashlib
import json
import shutil
from pathlib import Path

from .docker_util import ProbeError

FIXTURES = Path(__file__).resolve().parents[1] / "fixtures"
MANIFEST_FILE = FIXTURES / "backup-inputs.json"
# The container runs as a different uid than the test process and writes exports through the
# mount, so the directory has to be writable by whoever that turns out to be.
DIR_MODE = 0o777
FILE_MODE = 0o666


def digest_of(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def load_manifest(path: Path = MANIFEST_FILE) -> dict[str, str]:
    """The committed input set: file name -> sha256 of the bytes that belong there."""
    return dict(json.loads(path.read_text(encoding="utf-8")))


class BackupDir:
    """One host directory mounted into the MCP container as `GRAMPS_BACKUP_DIR`."""

    def __init__(
        self,
        path: Path | str,
        *,
        source_dir: Path | str = FIXTURES,
        manifest: dict[str, str] | None = None,
    ) -> None:
        self.path = Path(path)
        self.source_dir = Path(source_dir)
        self.manifest = dict(manifest) if manifest is not None else load_manifest()

    def reset(self) -> None:
        """Step 0 of a reset: nothing in here survives, and what lands is what was declared."""
        staged = {name: self._verified_bytes(name) for name in self.manifest}

        shutil.rmtree(self.path, ignore_errors=True)
        self.path.mkdir(parents=True)
        self.path.chmod(DIR_MODE)
        for name, data in staged.items():
            target = self.path / name
            target.write_bytes(data)
            target.chmod(FILE_MODE)

        landed = set(self.listing())
        if landed != set(self.manifest):
            raise ProbeError(f"reset left {sorted(landed)}, expected {sorted(self.manifest)}")

    def _verified_bytes(self, name: str) -> bytes:
        """Read one declared input, refusing anything that is not the committed file.

        Read *before* the directory is emptied, so a bad input leaves the previous state
        alone instead of destroying it and then failing.
        """
        source = self.source_dir / name
        if not source.is_file():
            raise ProbeError(f"declared backup input {name} is missing from {self.source_dir}")
        data = source.read_bytes()
        actual = digest_of(data)
        if actual != self.manifest[name]:
            raise ProbeError(
                f"{name} has digest {actual[:12]}…, the manifest says {self.manifest[name][:12]}… "
                "— regenerate the manifest deliberately, or restore the fixture"
            )
        return data

    def listing(self) -> dict[str, int]:
        """File name -> size, for everything currently in the directory."""
        if not self.path.is_dir():
            return {}
        return {entry.name: entry.stat().st_size for entry in sorted(self.path.iterdir())}

    def assert_export(self, before: dict[str, int], *, filename: str) -> Path:
        """Exactly `filename` appeared since `before`, and it has content."""
        after = self.listing()
        appeared = sorted(set(after) - set(before))

        assert appeared == [filename], (
            f"expected {filename!r} to appear in {self.path}, but this call added {appeared or 'nothing'}"
            f"\n  before={sorted(before)}\n  after={sorted(after)}"
        )
        assert after[filename] > 0, f"{filename} is empty — a failed export leaves that behind too"
        return self.path / filename
